"""Independent re-derivation of the expected ledger (written from the spec text)."""
import ipaddress, json, re

ALLOWED_METHOD = {"GET","HEAD","POST","PUT","PATCH","DELETE","OPTIONS"}
ALLOWED_SCHEME = {"http","https"}
PROHIB = {"connection","proxy-connection","keep-alive","transfer-encoding","upgrade","http2-settings","trailer"}
REPEAT = {"accept","accept-encoding","cache-control","if-match","if-none-match","pragma","vary"}
PSEUDO = {":method",":scheme",":authority",":path"}
TCHAR = set("abcdefghijklmnopqrstuvwxyz0123456789!#$%&'*+-.^_`|~")
PATHCH = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-._~!$&'()*+,;=:@/?")
HEX = set("0123456789abcdefABCDEF")

def o(s):
    return s.encode('latin-1') if all(ord(c) <= 255 for c in s) else None

def val_ok(v):
    if v == b"": return True
    edge = lambda c: (0x21 <= c <= 0x7e) or (0x80 <= c <= 0xff)
    if not edge(v[0]) or not edge(v[-1]): return False
    return all(edge(c) or c in (0x20, 0x09) for c in v[1:-1])

def name_ok(n):
    return bool(n) and all(chr(c) in TCHAR for c in n)

def path_ok(p):
    if p == b"*": return True
    if not p.startswith(b"/") or p.startswith(b"//"): return False
    i = 0
    while i < len(p):
        if p[i:i+1] == b"%":
            if i+2 >= len(p) or chr(p[i+1]) not in HEX or chr(p[i+2]) not in HEX: return False
            i += 3
        elif chr(p[i]) in PATHCH: i += 1
        else: return False
    return True

def host_norm(h):
    labs = h.split(b".")
    if len(labs) == 4 and all(l.isdigit() for l in labs):
        out = []
        for l in labs:
            if len(l) > 1 and l.startswith(b"0"): return None
            v = int(l)
            if v > 255: return None
            out.append(str(v))
        return ".".join(out)
    if not (1 <= len(h) <= 253): return None
    for l in labs:
        if not (1 <= len(l) <= 63): return None
        for c in l:
            if chr(c).lower() not in "abcdefghijklmnopqrstuvwxyz0123456789-" and c != 0x2d: return None
        if not (chr(l[0]).isalnum() and chr(l[-1]).isalnum()): return None
    return h.decode().lower()

def auth_norm(raw, scheme):
    if not raw: return None
    port = None
    if raw.startswith(b"["):
        j = raw.find(b"]")
        if j < 0: return None
        inner = raw[1:j]; rest = raw[j+1:]
        if b"%" in inner or b"[" in inner or b"]" in inner: return None
        try: addr = ipaddress.IPv6Address(inner.decode())
        except ValueError: return None
        h = "[" + addr.compressed + "]"
        if rest:
            if not rest.startswith(b":"): return None
            ps = rest[1:].decode()
            if not (1 <= len(ps) <= 5) or not ps.isdigit() or not ps.isascii(): return None
            port = int(ps)
            if not (1 <= port <= 65535): return None
    else:
        if raw.count(b":") > 1: return None
        if b":" in raw:
            hh, ps = raw.split(b":", 1)
        else:
            hh, ps = raw, b""
        h = host_norm(hh)
        if h is None: return None
        if ps:
            ps = ps.decode()
            if not (1 <= len(ps) <= 5) or not ps.isdigit() or not ps.isascii(): return None
            port = int(ps)
            if not (1 <= port <= 65535): return None
    if port is not None and port != (80 if scheme == "http" else 443):
        h += ":" + str(port)
    return h

def expected(scn):
    routes = scn["routes"]; events = scn["events"]
    pipes = {l: bytearray() for l in set(routes.values())}
    per = {}
    for i, e in enumerate(events):
        per.setdefault(e["sid"], []).append((i, e))
    out = []
    for sid in sorted(per):
        evs = per[sid]
        term = None
        for i, e in evs:
            if e["type"] in ("fin", "reset"): term = (i, e["type"])
        if term is None:
            out.append({"sid": sid, "status": "incomplete", "commit_at": None, "origin": None,
                        "offset": None, "length": 0, "cache_key": None}); continue
        if term[1] == "reset":
            out.append({"sid": sid, "status": "cancelled", "commit_at": None, "origin": None,
                        "offset": None, "length": 0, "cache_key": None}); continue
        seq = [(i, e) for i, e in evs if e["type"] in ("headers", "data")]
        kinds = [e["type"] for i, e in seq]
        body = b"".join(bytes.fromhex(e["hex"]) for i, e in seq if e["type"] == "data")
        secs = [e["fields"] for i, e in seq if e["type"] == "headers"]
        rec = {"sid": sid, "status": "rejected", "commit_at": None, "origin": None,
               "offset": None, "length": 0, "cache_key": None}
        nh = kinds.count("headers")
        if nh == 1:
            if kinds[0] != "headers" or any(k != "data" for k in kinds[1:]): out.append(rec); continue
            trail = None
        elif nh == 2:
            if kinds[0] != "headers" or kinds[-1] != "headers" or any(k != "data" for k in kinds[1:-1]):
                out.append(rec); continue
            trail = secs[1]
        else:
            out.append(rec); continue
        if len(body) > 65536: out.append(rec); continue
        init = secs[0]
        if sum(len(o(n)) + len(o(v)) + 32 for n, v in init) > 8192: out.append(rec); continue
        if trail is not None and sum(len(o(n)) + len(o(v)) + 32 for n, v in trail) > 8192: out.append(rec); continue
        pse = {}; reg = []; seen_reg = False; bad = False
        for n, v in init:
            if not val_ok(o(v)): bad = True; break
            if n.startswith(":"):
                if seen_reg or n not in PSEUDO or n in pse: bad = True; break
                pse[n] = o(v)
            else:
                seen_reg = True
                if not name_ok(o(n)): bad = True; break
                reg.append((o(n), o(v)))
        if bad: out.append(rec); continue
        if not all(k in pse for k in (":method", ":scheme", ":path")): out.append(rec); continue
        method = pse[":method"].decode(); scheme = pse[":scheme"].decode(); path = pse[":path"]
        if method not in ALLOWED_METHOD or scheme not in ALLOWED_SCHEME: out.append(rec); continue
        if path == b"*":
            if method != "OPTIONS": out.append(rec); continue
        elif not path_ok(path): out.append(rec); continue
        hosts = [v for n, v in reg if n == b"host"]
        if len(hosts) > 1: out.append(rec); continue
        auth = pse.get(":authority")
        if auth is None and not hosts: out.append(rec); continue
        if auth is not None and hosts and auth != hosts[0]: out.append(rec); continue
        raw_auth = auth if auth is not None else hosts[0]
        if not raw_auth: out.append(rec); continue
        ca = auth_norm(raw_auth, scheme)
        if ca is None: out.append(rec); continue
        names = [n for n, v in reg]
        if any(n in PROHIB for n in names): out.append(rec); continue
        tes = [v for n, v in reg if n == b"te"]
        if len(tes) > 1 or (tes and tes[0] != b"trailers"): out.append(rec); continue
        cls = [v for n, v in reg if n == b"content-length"]
        if cls:
            nums = set()
            for line in cls:
                for m in line.split(b","):
                    m = m.strip(b" \t")
                    if not m or not m.isdigit() or not m.isascii(): bad = True; break
                    nums.add(m.lstrip(b"0") or b"0")
                if bad: break
            if bad or len(nums) != 1 or nums.pop() != str(len(body)).encode(): out.append(rec); continue
        cnt = {}
        for n in names: cnt[n] = cnt.get(n, 0) + 1
        for n, c in cnt.items():
            if n in (b"host", b"te", b"content-length", b"cookie"): continue
            if c > 1 and not (n.decode() in REPEAT or (n.startswith(b"x-list-") and len(n) > 6)):
                bad = True; break
        if bad: out.append(rec); continue
        tps = []
        if trail is not None:
            for n, v in trail:
                if not val_ok(o(v)): bad = True; break
                if not (n.startswith("x-audit-") and len(n) > 8 and name_ok(o(n))): bad = True; break
                tps.append((o(n), o(v)))
        if bad: out.append(rec); continue
        rk = scheme + "://" + ca
        if rk not in routes: out.append(rec); continue
        origin = routes[rk]
        cookies = [v for n, v in reg if n == b"cookie"]
        lines = [method + " " + path.decode('latin-1') + " HTTP/1.1", "host: " + ca]
        done = False
        for n, v in reg:
            if n in (b"host", b"content-length", b"te"): continue
            if n == b"cookie":
                if done: continue
                done = True
                lines.append("cookie: " + "; ".join(x.decode('latin-1') for x in cookies)); continue
            lines.append(n.decode('latin-1') + ": " + v.decode('latin-1'))
        raw = ("\r\n".join(lines) + "\r\n").encode('latin-1')
        if trail is None:
            raw += ("content-length: %d\r\n\r\n" % len(body)).encode() + body
        else:
            raw += b"transfer-encoding: chunked\r\n"
            if tps:
                seen = []
                for n, v in tps:
                    if n not in seen: seen.append(n)
                raw += ("trailer: " + ", ".join(n.decode() for n in seen) + "\r\n").encode()
            raw += b"\r\n"
            if body:
                raw += ("%x\r\n" % len(body)).encode() + body + b"\r\n"
            raw += b"0\r\n"
            for n, v in tps:
                raw += n + b": " + v + b"\r\n"
            raw += b"\r\n"
        off = len(pipes[origin]); pipes[origin].extend(raw)
        out.append({"sid": sid, "status": "forwarded", "commit_at": term[0], "origin": origin,
                    "offset": off, "length": len(raw),
                    "cache_key": [method, scheme, ca, path.decode('latin-1')]})
    return {"streams": out, "origins": {l: bytes(b).hex() for l, b in pipes.items()}}
